//#region 源/核/指示文.ts
/**
* 指示文の組み立て．
*
* kawaiko に渡す指示文はどれも同じ数種類の節を並べ替えたものでしかないのに，
* 以前は 3 箇所で手ずからテンプレートを書いていて，そのうち 1 つが黙って
* ずれていた．節はここで一度だけ作り，ユースケース側はどれを使うか選ぶだけにする．
*
* 純粋な文字列処理．バインディングも I/O も無い．
*/
/**
* ひな型の `{{名前}}` を埋める．指示文の文言は，それを持つモジュールの隣の .md に
* 置いてある．差し込みはこれ一種類だけ．
*/
function 差し込む(ひな型, 値) {
	return 置き換える(ひな型, /\{\{([\p{L}\p{N}_]+)\}\}/gu, (全体, 鍵) => 値[鍵] ?? 全体);
}
/** 空の節を落としつつ，間に 1 行空けて連結する． */
function 節をつなぐ(...節一覧) {
	return 繋ぐ(絞る(写す(節一覧, (節) => 節 === void 0 ? "" : 前後の空白を落とす(節)), (節) => 節.length > 0), "\n\n");
}
/** 直近の会話．単発の発言ではなく会話に答えさせるため． */
function 会話ログ節(会話ログ) {
	if (前後の空白を落とす(会話ログ).length === 0) return "";
	return `${前後の空白を落とす(指示文_会話ログ_default)}\n${会話ログ}`;
}
/** 裏取り用の web 検索結果．無視してよいと明示してある． */
function 参考情報節(参考情報) {
	if (前後の空白を落とす(参考情報).length === 0) return "";
	return `${前後の空白を落とす(指示文_参考情報_default)}\n${参考情報}`;
}
/**
* このサーバーについて覚えたこと．
*
* 意図して「指示」ではなく「観測」として枠付けしてある．ここに入る事実はすべて
* ユーザーの発言に由来するので，命令のように読める「事実」が実行できてしまっては
* まずい．触るときもこの文言は残すこと．
*/
function 記憶節(事実一覧) {
	if (事実一覧.length === 0) return "";
	const 行 = 写す(取り出す事実(事実一覧), (事実) => {
		return `- ${事実.主語名 ?? (事実.主語の種別 === "server" ? "このサーバー" : "誰か")}: ${切り出す(置き換える(事実.本文, /\s+/g, " "), 0, 120)}`;
	});
	return もし(事実一覧.length === 0, {
		であれば: () => "",
		でなければ: () => 繋ぐ([前後の空白を落とす(指示文_記憶_default), ...行], "\n")
	});
}
function 取り出す事実(事実一覧) {
	return 事実一覧.slice(0, 10);
}
/** 次の一言をこれで組み立ててはいけない，という一覧． */
function 回避節(過去の発言) {
	const 行 = 絞る(写す(過去の発言, (発言) => 前後の空白を落とす(置き換える(発言, /\s+/g, " "))), (発言) => 発言.length > 0).slice(0, 6);
	if (行.length === 0) return "";
	return 繋ぐ([前後の空白を落とす(指示文_回避_default), ...写す(行, (発言) => `- ${切り出す(発言, 0, 80)}`)], "\n");
}
/**
* 1 発言ごとに振り直す型と長さ．これが無いとモデルは一つのリズムに落ち着き，
* チャンネルがテンプレ bot のように読め始める．
*/
function 抑揚節(乱数 = 数学.random) {
	return 繋ぐ([
		"今回の返しの型 (毎回変わる。直前と同じ型・同じ分量にはしない):",
		`- 型: ${返しの型を選ぶ(乱数)}`,
		`- 長さ: ${返しの長さを選ぶ(乱数)}`
	], "\n");
}
/** 抑揚と，常設の口調規則． */
function 文体節(乱数 = 数学.random) {
	return 節をつなぐ(抑揚節(乱数), 口調の規則);
}
/** 直前と同じ型で返ってきたときに，指示文の末尾へ足すもの． */
var 言い直しの指示 = 前後の空白を落とす(指示文_言い直し_default);
