//#region 源/核/定型文.ts
/**
* kawaiko の声で書いた在庫の一言．API 予算を使いたくない場面 — 利用制限，予算切れ，
* 異常，拒否，ループ — のために用意してある．
*
* 文面は 定型文.json にある．コードを触らずに調整できるように．同じ状況に何度
* 当たっても機械的に見えないよう，意図してばらつかせてある．`{m}` は該当する
* ものだけ「あと何分」に置き換わる．
*/
var 利用制限の文 = 定型文_default.利用制限;
var 予算超過の文 = 定型文_default.予算超過;
var 異常の文 = 定型文_default.異常;
var 拒否の文 = 定型文_default.拒否;
var 無言の文 = 定型文_default.無言;
/** 作り直しても直前と同じ文しか出てこなかったときの最後の逃げ道． */
var 反復打ち切りの文 = 定型文_default.反復打ち切り;
/** 「@kawaiko reset」への返事．設計上トークンを使わない． */
var リセットの文 = 定型文_default.リセット;
var 受け流しの文 = 定型文_default.受け流し;
/** 在庫から 1 つ選ぶ．`{m}` があれば「あと何分」を差し込む． */
function 定型文を選ぶ(候補, 変数, 乱数 = 数学.random) {
	return 候補[数学.floor(乱数() * 候補.length)].replace("{m}", 文字列(変数?.分 ?? 60));
}
