//#region 源/振る舞い/接続口.ts
/** 投げられた値を，保存する価値のある一行へ均す． */
function 失敗を要約する(err) {
	if (err instanceof Error) return `${err.name}: ${err.message}`.trim();
	try {
		return JSON.stringify(err);
	} catch {
		return String(err);
	}
}
