//#region 源/振る舞い/記憶操作.ts
async function 記憶を操作する(部品, 問い) {
	if (!部品.記憶庫.使えるか) return {
		状態: 503,
		本体: { 異常: "記憶庫が繋がっていない" }
	};
	switch (問い.種別) {
		case "サーバー一覧": return {
			状態: 200,
			本体: { サーバー一覧: await 部品.記憶庫.観測したサーバー() }
		};
		case "現状": return {
			状態: 200,
			本体: {
				サーバー: 問い.サーバーid,
				読み取り位置: await 部品.記憶庫.学習の読み取り位置(問い.サーバーid),
				事実一覧: await 部品.記憶庫.生きている事実(問い.サーバーid, { 上限: 200 }),
				学習の履歴: await 部品.記憶庫.学習の履歴(問い.サーバーid)
			}
		};
		case "回を取り消す": {
			const 成功か = await 部品.記憶庫.学習の回を取り消す(問い.サーバーid, 問い.識別子, 問い.理由);
			return 成功か ? {
				状態: 200,
				本体: {
					成功か,
					取り消した回: 問い.識別子
				}
			} : {
				状態: 500,
				本体: { 成功か: false }
			};
		}
		case "巻き戻す": {
			const 成功か = await 部品.記憶庫.時点まで巻き戻す(問い.サーバーid, 問い.連番, 問い.理由);
			return 成功か ? {
				状態: 200,
				本体: {
					成功か,
					戻した位置: 問い.連番
				}
			} : {
				状態: 500,
				本体: { 成功か: false }
			};
		}
	}
}
